    explanation: `トランスポート層の2大プロトコルがTCPとUDPである。TCPはコネクション型で、通信開始時に3ウェイハンドシェイクで接続を確立し、シーケンス番号による順序制御、確認応答、再送制御、フロー制御を行って信頼性の高い伝送を提供する。ファイル転送やWebなど確実性が必要な用途に使われる。UDPはコネクションレス型で、これらの制御を持たない代わりにヘッダが小さく遅延も少ないため、音声・映像のリアルタイム伝送やDNSの問合せなどに適する。用途に応じた使い分けが重要である。

【図解】TCPとUDPの比較
｜項目｜TCP｜UDP｜
｜接続形態｜コネクション型｜コネクションレス型｜
｜信頼性制御｜確認応答・再送あり｜なし｜
｜遅延・負荷｜大きめ｜小さい｜
｜主な用途｜Web・ファイル転送｜音声映像・DNS｜

【図解】使い分けの考え方
・1ビットも欠けてはならないデータ → TCP
・多少の欠落より遅延が問題になる用途 → UDP`,
    difficulty: 'standard',
