    correctKey: 'A',
    explanation: `ノンメタリック型光ファイバケーブルは、テンションメンバをFRP(繊維強化プラスチック)などの非金属材料とし、金属を全く含まないよう設計されたケーブルである。金属導体がないため、雷サージや電力線・電気鉄道からの電磁誘導による誘導電流が流れず、雷の多い地域、電力線との共架・並行区間、変電所構内などで大きな利点を持つ。金属部分への接地も不要になる。光ファイバ自体が絶縁体であるという特長を、ケーブル全体として活かした構造といえる。

【図解】ノンメタリック化のポイント
・テンションメンバ → FRPなど非金属に変更
・金属テープ外装 → 使用しない
・結果:誘導電流の流れる経路がない

【図解】採用が有効な場所
｜場所｜理由｜
｜雷多発地域｜誘導雷サージ対策｜
｜電力線併架・並行区間｜電磁誘導対策｜
｜変電所・電気鉄道沿線｜強電界環境対策｜`,
