    correctKey: 'B',
    explanation: `光ファイバケーブルのけん引布設では、張力を光ファイバ心線に伝えず、ケーブル中心の抗張力体(テンションメンバ)に負担させることが基本である。このため、けん引端にはプーリングアイや現場取付け形のけん引端末を取り付けて、テンションメンバと外被に張力が分散するよう処理する。けん引時は張力計で常時監視し、製造者の定める許容張力を超えないようにする。長距離や屈曲の多い区間では、中間で人力補助や中間けん引装置を使い、また撚れ防止のためより戻し金物(スイベル)を介してけん引する。

【図解】けん引布設の要点
・けん引端:プーリングアイで張力をテンションメンバへ
・張力管理:張力計で監視し許容値以下を維持
・撚れ防止:より戻し金物(スイベル)を使用
・長区間:中間けん引・人力補助を併用

【図解】守るべき管理値
｜項目｜管理内容｜
｜けん引張力｜許容張力以下｜
｜曲げ半径｜布設時は外径の20倍以上｜
｜側圧｜金車径の適正化で低減｜`,
    difficulty: 'standard',
