    choices: [
      { key: 'A', text: 'STPは、ネットワークの伝送速度を物理的に高速化するプロトコルである', explanation: '誤り。STPは速度向上ではなくループ防止のためのプロトコルである。' },
      { key: 'B', text: 'STPは、冗長構成で生じるレイヤ2のループを、一部ポートをブロッキングして論理的に切断することで防止する', explanation: '正しい。ループを防ぎつつ、障害時は経路を切り替えて冗長性を確保する。' },
      { key: 'C', text: 'レイヤ2ネットワークにループがあっても、ブロードキャストフレームは自然に消滅するため対策は不要である', explanation: '誤り。L2フレームには生存時間がなく、ループでは無限に循環し帯域を埋め尽くす。' },
      { key: 'D', text: 'STPはIPアドレスの重複を検出するためのプロトコルである', explanation: '誤り。IPアドレスの管理とは無関係で、L2トポロジの制御を行う。' },
    ],
    correctKey: 'B',
    explanation: `スイッチを冗長に接続するとレイヤ2の経路にループができる。イーサネットフレームにはIPパケットのような生存時間の仕組みがないため、ループ内でブロードキャストフレームが無限に循環・増殖するブロードキャストストームが発生し、ネットワーク全体が停止してしまう。STPは、スイッチ間でBPDUという制御フレームを交換してルートブリッジを決定し、ループとなる一部のポートをブロッキング状態にして論理的にツリー構造を作ることでループを防止する。障害時にはブロックを解除して経路を切り替え、冗長性も確保する。

【図解】STPの動作の流れ
・BPDUの交換 → ルートブリッジを選出
・各スイッチが最適経路を計算
・ループになるポートをブロッキング
・障害検出時はブロック解除で経路切替

【図解】ループ放置時の障害
｜現象｜影響｜
｜ブロードキャストストーム｜帯域を埋め尽くす｜
｜MACテーブルの不安定化｜転送先が定まらない｜
｜結果｜ネットワーク全体の停止｜`,
