    subjectName: '電気通信設備',
    question: '携帯電話の高速化技術に関する記述として、適当なものはどれか。',
    choices: [
      { key: 'A', text: 'キャリアアグリゲーションは、1つの搬送波の帯域を狭くして品質を上げる技術である', explanation: '誤り。複数の搬送波を束ねて広帯域化する技術である。' },
      { key: 'B', text: 'MIMOはアンテナを1本に減らして消費電力を下げる技術である', explanation: '誤り。MIMOは複数アンテナによる空間多重で速度を高める技術である。' },
      { key: 'C', text: 'キャリアアグリゲーションは複数の周波数帯の搬送波を束ねて同時使用し、実効的な伝送帯域を拡大する技術である', explanation: '正しい。異なるバンドの組合せで大幅な高速化が図れる。' },
      { key: 'D', text: '適応変調とは、電波状態にかかわらず常に同じ変調方式を使い続けることである', explanation: '誤り。適応変調は電波状態に応じて変調方式・符号化率を切り替える技術である。' },
    ],
    correctKey: 'C',
    explanation: `携帯電話の高速化は複数技術の積み重ねで実現されている。キャリアアグリゲーション(CA)は、異なる周波数帯にある複数の搬送波(コンポーネントキャリア)を束ねて同時に使用し、実効帯域幅を拡大する技術で、LTE-Advanced以降の高速化の柱である。MIMOは複数アンテナによる空間多重で同一帯域の伝送量を増やす。適応変調・符号化(AMC)は、電波状態が良いときは多値変調・高符号化率で高速に、悪いときは頑健な設定に切り替えて、スループットと安定性を両立させる。

【図解】主な高速化技術
｜技術｜原理｜
｜キャリアアグリゲーション｜複数搬送波を束ねて広帯域化｜
｜MIMO｜複数アンテナの空間多重｜
｜適応変調・符号化｜電波状態に応じた最適化｜

【図解】CAのイメージ
・バンドAの20MHz＋バンドBの20MHzを同時使用
・実効帯域40MHz分の速度を実現
・組み合わせるバンド数を増やすほど高速化`,
