    choices: [
      { key: 'A', text: '遅延・ジッタ・パケット損失は音声品質を劣化させる主要因であり、QoSによる優先制御が有効な対策となる', explanation: '正しい。リアルタイム性が求められる音声はネットワーク品質に敏感である。' },
      { key: 'B', text: '音声パケットはどれだけ遅延しても通話品質には影響しない', explanation: '誤り。大きな遅延は会話の応答性を損ない、品質を劣化させる。' },
      { key: 'C', text: 'ジッタとは音声の音量が大きくなる現象である', explanation: '誤り。ジッタはパケット到着間隔の揺らぎのことである。' },
      { key: 'D', text: 'パケット損失は再送により常に完全に回復できるため問題ない', explanation: '誤り。リアルタイムの音声では再送が間に合わず、音切れとして現れる。' },
    ],
    correctKey: 'A',
    explanation: `IP電話の音声品質は、ネットワークの3つの品質指標に大きく左右される。遅延(エンドツーエンドの伝送時間)が大きいと会話の応答が間延びし、一般に片道150ms以下が目安とされる。ジッタ(到着間隔の揺らぎ)は受信側の揺らぎ吸収バッファで平滑化するが、大きすぎると遅延増加や音切れになる。パケット損失は音の途切れとして直接品質を損なう。音声はUDP/RTPで運ばれ再送による回復ができないため、QoSによる音声パケットの優先制御と帯域設計が品質確保の基本対策となる。品質の総合評価にはR値やMOS値が使われる。

【図解】音声品質の3大劣化要因
｜要因｜内容｜影響｜
｜遅延｜伝送時間の増大｜会話の間延び｜
｜ジッタ｜到着間隔の揺らぎ｜音切れ・遅延増｜
｜パケット損失｜データの欠落｜音の途切れ｜

【図解】品質確保の対策
・QoS:音声パケットの優先転送
・帯域設計:同時通話数分の帯域確保
・評価:R値・MOS値による品質管理`,
