【図解】非常放送の連動動作
・自動火災報知設備が火災を検出
・火災信号で非常放送が自動起動
・業務放送・BGMを遮断し緊急放送を最優先
・出火階・直上階などへ順次放送

【図解】非常放送設備の要件
｜項目｜内容｜
｜非常電源｜蓄電池による停電時動作｜
｜配線｜耐熱電線等で機能維持｜
