    question: 'SPD(サージ防護デバイス)に関する記述として、適当なものはどれか。',
    choices: [
      { key: 'A', text: 'SPDは、通信信号を増幅するための能動素子である', explanation: '誤り。SPDは雷サージから機器を保護する保護デバイスである。' },
      { key: 'B', text: 'SPDは雷サージなどの過電圧を検出すると低インピーダンスとなり、サージ電流を接地側へ流して機器を保護する', explanation: '正しい。平常時は高インピーダンスで回路に影響を与えない。' },
      { key: 'C', text: 'SPDを設置すれば、接地工事は不要になる', explanation: '誤り。SPDはサージを接地へ逃がす素子であり、良好な接地が前提である。' },
      { key: 'D', text: 'SPDは一度動作しても劣化しないため、点検・交換は不要である', explanation: '誤り。サージ処理により劣化するため、劣化表示の確認や交換が必要である。' },
    ],
    correctKey: 'B',
    explanation: `SPDは、電源線や通信線に侵入する雷サージなどの過渡的な過電圧から機器を保護するデバイスである。平常時は高インピーダンスで回路に影響を与えず、過電圧が加わると瞬時に低インピーダンスに転じてサージ電流を接地側へバイパスし、機器端子間の電圧を耐電圧以下に抑える。効果を発揮するには、良好な接地と、接地線を短く太く配線することが不可欠である。SPDはサージを処理するたびに素子が劣化するため、劣化表示窓の確認や定期交換などの保守も必要である。電源用・通信用など用途別の製品を適切に選定する。

【図解】SPDの動作
・平常時:高インピーダンス(回路に無影響)
・サージ侵入時:低インピーダンス化
・サージ電流を接地へバイパス
・機器にかかる電圧を制限

【図解】設置・保守の要点
｜項目｜内容｜
｜接地｜低い接地抵抗・短く太い接地線｜
｜選定｜電源用・通信用など用途別に選定｜
｜保守｜劣化表示の確認・交換｜`,
    difficulty: 'basic',
