    correctKey: 'C',
    explanation: `電線共同溝(C.C.BOX)は、道路の地下に設けられ、電力線・通信線などの電線類を共同で収容する施設である。無電柱化により、台風・地震時の電柱倒壊や断線の防止(防災性向上)、歩行空間の確保、都市景観の向上が図られる。特殊部(分岐部・接続部)と管路部で構成され、複数の占用事業者が収容するため、区画割りや入溝・施工時の事業者間調整、管理区分の明確化が運用上重要である。情報ボックスは、道路管理者が設ける光ファイバ収容用の管路施設で、道路管理用通信網や民間開放にも使われる。

【図解】電線共同溝の構成
・管路部:各事業者のケーブルを収容
・特殊部:分岐・接続・引込みの空間
・地上機器:変圧器等(電力)の設置

【図解】地中化・共同収容の効果
｜項目｜効果｜
｜防災｜電柱倒壊・断線の防止｜
｜景観・歩行空間｜電柱・架空線の解消｜
｜運用｜占用者間の調整が必要｜`,
